1	package fleet
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"net/http"
7		"net/http/httptest"
8		"sync"
9		"testing"
10		"time"
11	)
12	
13	// --- response types and helpers ---------------------------------------------
14	
15	type configPublishResponse struct {
16		RequestID   string          `json:"requestId"`
17		Version     int64           `json:"version"`
18		Config      json.RawMessage `json:"config"`
19		PublishedAt time.Time       `json:"publishedAt"`
20	}
21	
22	type configViewResponse struct {
23		Version     int64           `json:"version"`
24		Config      json.RawMessage `json:"config"`
25		PublishedAt time.Time       `json:"publishedAt"`
26	}
27	
28	type configReceiptResponse struct {
29		ReceiptID  string    `json:"receiptId"`
30		Version    int64     `json:"version"`
31		Success    bool      `json:"success"`
32		Reason     string    `json:"reason"`
33		ReceivedAt time.Time `json:"receivedAt"`
34	}
35	
36	type configStatusResponse struct {
37		TargetVersion  int64  `json:"targetVersion"`
38		AppliedVersion int64  `json:"appliedVersion"`
39		FailureReason  string `json:"failureReason"`
40	}
41	
42	func publishBody(requestID string, base int64, config string) string {
43		return fmt.Sprintf(`{"requestId":%q,"baseVersion":%d,"config":%s}`, requestID, base, config)
44	}
45	
46	func receiptBody(receiptID string, version int64, success bool, reason string) string {
47		if reason != "" {
48			return fmt.Sprintf(`{"receiptId":%q,"version":%d,"success":%v,"reason":%q}`, receiptID, version, success, reason)
49		}
50		return fmt.Sprintf(`{"receiptId":%q,"version":%d,"success":%v}`, receiptID, version, success)
51	}
52	
53	func publishConfig(t *testing.T, h http.Handler, device, body string, wantStatus int) configPublishResponse {
54		t.Helper()
55		r := doRequest(t, h, http.MethodPost, fmt.Sprintf("/v1/devices/%s/configs", device), body)
56		if r.Code != wantStatus {
57			t.Fatalf("publish status = %d, want %d: %s", r.Code, wantStatus, r.Body.String())
58		}
59		if wantStatus == http.StatusCreated || wantStatus == http.StatusOK {
60			return decodeBody[configPublishResponse](t, r)
61		}
62		return configPublishResponse{}
63	}
64	
65	func postReceipt(t *testing.T, h http.Handler, device, body string, wantStatus int) configReceiptResponse {
66		t.Helper()
67		r := doRequest(t, h, http.MethodPost, fmt.Sprintf("/v1/devices/%s/configs/receipts", device), body)
68		if r.Code != wantStatus {
69			t.Fatalf("receipt status = %d, want %d: %s", r.Code, wantStatus, r.Body.String())
70		}
71		if wantStatus == http.StatusCreated || wantStatus == http.StatusOK {
72			return decodeBody[configReceiptResponse](t, r)
73		}
74		return configReceiptResponse{}
75	}
76	
77	func getPending(t *testing.T, h http.Handler, device string) *httptest.ResponseRecorder {
78		t.Helper()
79		return doRequest(t, h, http.MethodGet, fmt.Sprintf("/v1/devices/%s/configs/pending", device), "")
80	}
81	
82	func getConfigStatus(t *testing.T, h http.Handler, device string) configStatusResponse {
83		t.Helper()
84		r := doRequest(t, h, http.MethodGet, fmt.Sprintf("/v1/devices/%s/configs/status", device), "")
85		if r.Code != http.StatusOK {
