249	func TestConfigRequestDedupComparesNumbersExactly(t *testing.T) {
250		store, clock := newClockStore()
251		h := NewHandler(store)
252		mustRegister(t, h, "gw")
253	
254		publishConfig(t, h, "gw", publishBody("req-1", 0,
255			`{"big":9007199254740992,"frac":0.1,"zero":0,"nested":{"a":[1,2]}}`), http.StatusCreated)
256		firstTime := clock.UTC()
257		*clock = clock.Add(time.Hour)
258	
259		// Numbers that only share a float64 (precision loss or underflow to zero)
260		// are different content, at any nesting depth.
261		changed := []string{
262			`{"big":9007199254740993,"frac":0.1,"zero":0,"nested":{"a":[1,2]}}`,
263			`{"big":9007199254740992,"frac":0.10000000000000001,"zero":0,"nested":{"a":[1,2]}}`,
264			`{"big":9007199254740992,"frac":0.1,"zero":1e-400,"nested":{"a":[1,2]}}`,
265			`{"big":9007199254740992,"frac":0.1,"zero":0,"nested":{"a":[1,9007199254740993]}}`,
266			`{"big":9007199254740992,"frac":0.1,"zero":0,"nested":{"a":[1,"2"]}}`,
267		}
268		for _, config := range changed {
269			if r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/configs",
270				publishBody("req-1", 0, config)); r.Code != http.StatusConflict {
271				t.Fatalf("changed content %s => %d, want 409", config, r.Code)
272			}
273		}
274		// The rejected retries created nothing and changed nothing.
275		status := getConfigStatus(t, h, "gw")
276		if status.TargetVersion != 1 || status.AppliedVersion != 0 {
277			t.Fatalf("rejected retries changed state: %+v", status)
278		}
279		configs := listConfigs(t, h, "gw")
280		if len(configs) != 1 || string(configs[0].Config) != `{"big":9007199254740992,"frac":0.1,"zero":0,"nested":{"a":[1,2]}}` {
281			t.Fatalf("rejected retries rewrote history: %+v", configs)
282		}
283	
284		// Same value in a different notation is still the same content: the retry
285		// returns the first result with the first publish time and content.
286		retry := publishConfig(t, h, "gw", publishBody("req-1", 0,
287			`{ "zero" : -0.000 , "frac" : 0.10000 , "big" : 9007199254740992.0 , "nested" : { "a" : [ 1e0 , 2.000 ] } }`), http.StatusOK)
288		if retry.Version != 1 || !retry.PublishedAt.Equal(firstTime) {
289			t.Fatalf("retry = %+v, want version 1 at first time %s", retry, firstTime)
290		}
291		if string(retry.Config) != `{"big":9007199254740992,"frac":0.1,"zero":0,"nested":{"a":[1,2]}}` {
292			t.Fatalf("retry rewrote stored content: %s", retry.Config)
293		}
294		if status := getConfigStatus(t, h, "gw"); status.TargetVersion != 1 {
295			t.Fatalf("target after retry = %d, want 1", status.TargetVersion)
296		}
297	}
