332	func TestConfigPublishKeepsOutOfRangeNumbersExact(t *testing.T) {
333		store, clock := newClockStore()
334		h := NewHandler(store)
335		mustRegister(t, h, "gw")
336	
337		// A legal JSON number larger than MaxFloat64 (or smaller than the smallest
338		// positive subnormal) must publish at any nesting depth and come back
339		// byte-for-byte, never as Infinity, zero, a string or a rounded value.
340		large := `{"range":1e309,"nested":{"steps":[-1e309,1e-400]}}`
341		first := publishConfig(t, h, "gw", publishBody("req-1", 0, large), http.StatusCreated)
342		if first.Version != 1 {
343			t.Fatalf("version = %d, want 1", first.Version)
344		}
345		if string(first.Config) != large {
346			t.Fatalf("publish result changed number: %s", first.Config)
347		}
348		firstTime := clock.UTC()
349	
350		// History keeps the exact literals.
351		if configs := listConfigs(t, h, "gw"); len(configs) != 1 || string(configs[0].Config) != large {
352			t.Fatalf("history changed number: %+v", configs)
353		}
354		// The simulated device pull serves the exact literals as the pending target.
355		r := getPending(t, h, "gw")
356		if r.Code != http.StatusOK {
357			t.Fatalf("pending = %d, want 200", r.Code)
358		}
359		if pending := decodeBody[configViewResponse](t, r); string(pending.Config) != large {
360			t.Fatalf("pending changed number: %s", pending.Config)
361		}
362	
363		// Same value in a different notation (10e308 == 1e309 exactly) is an
364		// idempotent retry: 200 with the first version, time and stored content.
365		*clock = clock.Add(time.Hour)
366		retry := publishConfig(t, h, "gw", publishBody("req-1", 0,
367			`{ "nested" : { "steps" : [ -10e308 , 10e-401 ] } , "range" : 10e308 }`), http.StatusOK)
368		if retry.Version != 1 || !retry.PublishedAt.Equal(firstTime) {
369			t.Fatalf("equal-value retry = %+v, want v1 at first time %s", retry, firstTime)
370		}
371		if string(retry.Config) != large {
372			t.Fatalf("retry rewrote stored content: %s", retry.Config)
373		}
374		if status := getConfigStatus(t, h, "gw"); status.TargetVersion != 1 {
375			t.Fatalf("retry created a version: %+v", status)
376		}
377	
378		// A genuinely different out-of-range value conflicts and adds nothing.
379		if r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/configs",
380			publishBody("req-1", 0, `{"range":2e309,"nested":{"steps":[-1e309,1e-400]}}`)); r.Code != http.StatusConflict {
381			t.Fatalf("different value = %d, want 409", r.Code)
382		}
383		if configs := listConfigs(t, h, "gw"); len(configs) != 1 {
384			t.Fatalf("409 added a version: %+v", configs)
385		}
386	}
