531		receipt := postReceipt(t, h, "gw", receiptBody("rc-1", 1, true, ""), http.StatusCreated)
532		if receipt.Version != 1 || !receipt.Success || receipt.Reason != "" || receipt.ReceivedAt.IsZero() {
533			t.Fatalf("receipt = %+v", receipt)
534		}
535		status := getConfigStatus(t, h, "gw")
536		if status.TargetVersion != 1 || status.AppliedVersion != 1 {
537			t.Fatalf("status = %+v", status)
538		}
539		if r := getPending(t, h, "gw"); r.Code != http.StatusNoContent {
540			t.Fatalf("pending = %d, want 204", r.Code)
541		}
542	}
