550		if fail.Reason != "disk full" {
551			t.Fatalf("failure receipt = %+v", fail)
552		}
553		status := getConfigStatus(t, h, "gw")
554		if status.AppliedVersion != 0 || status.FailureReason != "disk full" {
555			t.Fatalf("status after failure = %+v", status)
556		}
557		// Failure does not advance; latest config stays readable for retry.
558		if r := getPending(t, h, "gw"); r.Code != http.StatusOK {
559			t.Fatalf("pending after failure = %d, want 200", r.Code)
560		}
561		// A later success clears the failure reason.
562		postReceipt(t, h, "gw", receiptBody("rc-ok", 1, true, ""), http.StatusCreated)
563		status = getConfigStatus(t, h, "gw")
