642		publishConfig(t, h, "gw", publishBody("r1", 0, `{"v":1}`), http.StatusCreated)
643		first := postReceipt(t, h, "gw", receiptBody("rc-f", 1, false, "boom"), http.StatusCreated)
644		firstReceived := first.ReceivedAt
645	
646		*clock = clock.Add(time.Hour)
647		// Same receiptId + same content retries with 200 and the first time; it
648		// must not be appended again.
649		retry := postReceipt(t, h, "gw", receiptBody("rc-f", 1, false, "boom"), http.StatusOK)
650		if !retry.ReceivedAt.Equal(firstReceived) {
