659		for _, body := range []string{
660			receiptBody("rc-f", 1, true, ""),
661			receiptBody("rc-f", 1, false, "other"),
662		} {
663			if r := doRequest(t, h, http.MethodPost, "/v1/devices/gw/configs/receipts", body); r.Code != http.StatusConflict {
664				t.Fatalf("changed receipt %s => %d, want 409", body, r.Code)
665			}
666		}
