672		postReceipt(t, h, "gw", receiptBody("rc-ok", 1, true, ""), http.StatusCreated)
673		// Re-reporting the old failure id still retries as 200 (stored first result)
674		// rather than becoming a new conflict against applied state.
675		postReceipt(t, h, "gw", receiptBody("rc-f", 1, false, "boom"), http.StatusOK)
676	}
