p = 'internal/fleet/config.go'
s = open(p).read()
old = '''	for i := len(cfg.receipts) - 1; i >= 0; i-- {
		receipt := cfg.receipts[i]
		if !receipt.Success && receipt.Version > cfg.applied {
			status.FailureReason = receipt.Reason
			break
		}
	}
	return status, nil'''
new = '''	// WRONG: any success wipes every earlier failure.
	lastSuccess := -1
	for i, receipt := range cfg.receipts {
		if receipt.Success {
			lastSuccess = i
		}
	}
	for i := len(cfg.receipts) - 1; i > lastSuccess; i-- {
		receipt := cfg.receipts[i]
		if !receipt.Success && receipt.Version > cfg.applied {
			status.FailureReason = receipt.Reason
			break
		}
	}
	return status, nil'''
assert old in s
open(p,'w').write(s.replace(old,new))
EOF
go test ./internal/fleet/ -run 'TestConfigFailureReason' -count=1; echo "exit=$?"
